/** The nonlinear solve's and the buckling's messages, translated inside the notes that carry them (S5). */
const S5_MESSAGES_EL: [RegExp, (m: RegExpExecArray) => string][] = [
  [/^Second order: unstable, the loads are past the critical ones \(αcr < 1\)\.$/, () => "Δεύτερη τάξη: ασταθές, τα φορτία έχουν ξεπεράσει τα κρίσιμα (αcr < 1)."],
  [/^A mechanism once 1 members? went slack: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `Μηχανισμός μετά τη χαλάρωση 1 μέλους: τίποτα δεν συγκρατεί τον κόμβο ${m[1]} (${m[2]}).`],
  [/^A mechanism once (\d+) members? went slack: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `Μηχανισμός μετά τη χαλάρωση ${m[1]} μελών: τίποτα δεν συγκρατεί τον κόμβο ${m[2]} (${m[3]}).`],
  [/^A mechanism once 1 members? went slack and (\d+) supports? lifted: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `Μηχανισμός μετά τη χαλάρωση 1 μέλους και την ανύψωση ${m[1]} στηρίξεων: τίποτα δεν συγκρατεί τον κόμβο ${m[2]} (${m[3]}).`],
  [/^A mechanism once (\d+) members? went slack and (\d+) supports? lifted: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `Μηχανισμός μετά τη χαλάρωση ${m[1]} μελών και την ανύψωση ${m[2]} στηρίξεων: τίποτα δεν συγκρατεί τον κόμβο ${m[3]} (${m[4]}).`],
  [/^A mechanism at node (\S+) \(([^)]*)\)\.$/, (m) => `Μηχανισμός στον κόμβο ${m[1]} (${m[2]}).`],
  [/^The one-way members and supports did not settle: they go back to states already tried\.$/, () => "Τα μέλη και οι στηρίξεις μιας κατεύθυνσης δεν συγκλίνουν: επανέρχονται σε καταστάσεις που έχουν ήδη δοκιμαστεί."],
  [/^Not settled in (\d+) iterations\.$/, (m) => `Δεν συνέκλινε σε ${m[1]} επαναλήψεις.`],
  [/^No buckling under these loads: the geometric stiffness only stiffens\.$/, () => "Καμπτικός λυγισμός δεν εμφανίζεται με αυτά τα φορτία: η γεωμετρική ακαμψία απλώς ενισχύει."],
  [/^No buckling mode: the compressed bars are held by what is round them\.$/, () => "Καμία μορφή λυγισμού: οι θλιβόμενες ράβδοι συγκρατούνται από ό,τι τις περιβάλλει."],
  [/^A mechanism in its last states\.$/, () => "Μηχανισμός στις τελευταίες καταστάσεις."],
];
function s5msgEl(text: string): string {
  for (const [re, f] of S5_MESSAGES_EL) { const x = re.exec(text); if (x) return f(x); }
  return text;
}
function s5dSegEl(t: string): string {
  const a = /^φ up to 1\/(\d+) along (X|Y)(?: \(m = ([\d.]+)\))?$/.exec(t);
  if (a) return a[3] ? `φ έως 1/${a[1]} κατά ${a[2]} (m = ${a[3]})` : `φ έως 1/${a[1]} κατά ${a[2]}`;
  const b = /^no column along (X|Y)$/.exec(t);
  return b ? `κανένα υποστύλωμα κατά ${b[1]}` : t;
}
